local UIBambooCheckpointDialog = Class("UIBambooCheckpointDialog")

function UIBambooCheckpointDialog:__init() 
    self._activityUuid = 0 
    self._activityId = 0           --当前活动id
    self._allChapter = {}          --所有的章节
    self._buffs = {}               --所有的buff
    self._roles = {}               --所有的角色
    self._mapId = 0                --当前的地图id
    self._mapVo = nil              --vo

    self._isShowBuff = true        --是否显示buff
    self._allCo = {}
end

function UIBambooCheckpointDialog:__delete()
    self._activityUuid = nil 
    self._activityId = nil          
    self._allChapter = nil     
    self._buffs = nil     
    self._roles = nil        
    self._mapId = nil          
    self._isShowBuff = nil       
    self._mapVo = nil              --vo 
    self._allCo = {}
end

function UIBambooCheckpointDialog:Awake()
    GameUtils.RefreshTopGoods(Constants.UITypeIds.UIBambooCheckpointDialog)
    self.EventBambooMainStatus = Events.AddListener(Constants.EventNames.EventBambooMainStatus, Bind(self, self.OnPageStatus))
    self.EventBambooActivityEnd = Events.AddListener(Constants.EventNames.BambooActivityEnd, Bind(self, self.OnActiveEnd))
    self.EventBambooBuffChange = Events.AddListener(Constants.EventNames.BambooBuffChange, Bind(self, self.OnBambooBuffChange))
    self.EventBamBooMgrClear = Events.AddListener(Constants.EventNames.BamBooMgrClear, Bind(self, self.OnBamBooMgrClear))

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._activityUuid = checkNumber(argument.activityUuid)  
    if self._activityUuid == 0 then
        return
    end

    self._activityId = BambooUtils.GetActivityId(self._activityUuid)    --活动id
    if self._activityId == 0 then
        return
    end
    self._mapId = checkNumber(argument.mapId)  
    if self._mapId == 0 then
        return
    end

    self._mapVo = BambooUtils.GetBambooActivityCopyVo(self._mapId)
    if not self._mapVo then
        return
    end

    self:InitData()

    self.CatEmotion = self.controller.gameObject.transform:Find("Root/CatEmotion")


    --GameUtils.ShowBlackOverlay()
    GameUtils.ShowBlackOverlay(nil, function()
        while not BambooMgr:GetInstance()._isLodeSuccess do
            coroutine.yield(Yielders.EndOfFrame)
        end
    end)

    CfUtils.SetActive(self.BtnReward, not BambooUtils.IsPassMap(self._mapId))
end

--初始化数据
function UIBambooCheckpointDialog:InitData()
    self._roles = BambooUtils.GetAllRole()

    self._buffs = {}
    local t = BambooUtils.GetAllBuff()
    if t then
        for k, v in pairs(t) do
            table.insert(self._buffs, v)
        end
    end
end

function UIBambooCheckpointDialog:FillSelf()
    SetButtonAction(self.BtnGiveUp, Bind(self, self.OnBtnGiveUp))
    SetButtonAction(self.BtnReward, Bind(self, self.OnBtnShowRewards))

    self:FillTitleName()
    self:FillBuffs()
    self:FillTeamMembers()
end

--绘制标题
function UIBambooCheckpointDialog:FillTitleName()

end

--绘制buff
function UIBambooCheckpointDialog:FillBuffs(isRefresh)
    CfUtils.SetActive(self.BuffBg, true)
    if not self._buffs or table.count(self._buffs) <= 0 then
        return
    end

    local newBuffId = BambooQuestComponent:GetNewBuffId()
    for k, v in pairs(self._buffs) do
        local go = self["Point"..k]
        CfUtils.SetActive(go, true)
        self:FillBuff(go, v, k == #self._buffs, isRefresh, newBuffId)
    end
end

function UIBambooCheckpointDialog:FillBuff(go, data, isLast, isRefresh, newBuffId)
    if not go or not data then
        return
    end
    local scr = CfUtils.GetLuaScr(go.transform:Find("BambooCheckpointBuffNode"), UIBambooCheckpointBuffNode)
    if scr then
        scr:Refresh(data, function()
            self._isClickBuff = true
        end)
        --新增一个刷新的时候最后一个为新增的
        if isRefresh then
        --    if isLast then
            if checkNumber(newBuffId) == checkNumber(data) then
                local co = cs_coroutine.start(function()
                    scr:PlayAni("Activate")  
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.333))
                    scr:OnClick()
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(3))

                    local tipGo = GameObject.Find("CommonTipsBoardBuff")
                    if not isNull(tipGo) then
                        Events.Broadcast("DestoryCommonTipsBord", nil)
                        scr:RefreshSelect(false) 
                    end 
                end)
                table.insert(self._allCo, co)
            end
        else
            if checkNumber(newBuffId) == checkNumber(data) then
                local co = cs_coroutine.start(function()
                    scr:PlayAni("Activate")  
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1.333))
                    scr:OnClick()
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(3))

                    local tipGo = GameObject.Find("CommonTipsBoardBuff")
                    if not isNull(tipGo) then
                        Events.Broadcast("DestoryCommonTipsBord", nil)
                        scr:RefreshSelect(false) 
                    end 
                end)
                table.insert(self._allCo, co)
            else
                scr:PlayAni("Activate")
                scr:RefreshSelect(false)  
            end
        end
    end
end

