--绘制队员
function UIBambooCheckpointDialog:FillTeamMembers()
    if not self._roles then
        return
    end

    local scr = CfUtils.GetLuaScr(self.UITeamMembersNode, UITeamMembersNode)
	if scr then
		scr:Refresh(self._roles, false, 0.6, nil, true)
		--scr:RefreshSpacing(0)
	end
end

--刷新奖励
function UIBambooCheckpointDialog:RefreshReward()
    local t = RewardConfMgr:GetInstance():_GetRewardData(CfUtils.Split(self._mapVo.reward), CfUtils.Split(self._mapVo.rewardNum))
    GameUtils.ShowCommonTipsBoardRewardPreview(self.BtnReward.gameObject, t, localize('奖励预览:'), false)
end

--buff展示按钮
function UIBambooCheckpointDialog:OnBtnShowBuff()
    KTool.SetActive(self.BuffBg, not self._isShowBuff)
    self._isShowBuff = not self._isShowBuff
end

--展示奖励
function UIBambooCheckpointDialog:OnBtnShowRewards()
    self:RefreshReward()
end

--放弃按钮
function UIBambooCheckpointDialog:OnBtnGiveUp()
    GameUtils.SecondConfirm(localize("是否放弃当前副本"), function()
        BambooQuestComponent:ActivityQuestRenounceQuestReq(self._activityUuid, function()
            self:CloseSelf()
        end)
    end)
end

--退出按钮
function UIBambooCheckpointDialog:OnBtnClose()
    self:CloseSelf()
end

--界面显示隐藏
function UIBambooCheckpointDialog:OnPageStatus(body)
    if not body then 
        return
    end
    if body.isTrue then
        self.controller.gameObject.transform.anchoredPosition = Vector2(0, 0)
        self:CheckRewardOrFinish()
    else
        self.controller.gameObject.transform.anchoredPosition = Vector2(9999, 9999)
    end
end

--buff刷新
function UIBambooCheckpointDialog:OnBambooBuffChange()
    self._buffs = {}
    local t = BambooUtils.GetAllBuff()
    if t then
        for k, v in pairs(t) do
            table.insert(self._buffs, v)
        end
    end

    self:FillBuffs(true)
end

--活动结束
function UIBambooCheckpointDialog:OnActiveEnd()
    GameUtils.SecondConfirm(localize("活动已结束"), function()
        BambooQuestComponent:ClearCurMapInfo()
        self:CloseSelf()
    end, function()
        BambooQuestComponent:ClearCurMapInfo()
        self:CloseSelf()
    end)
end

--处理奖励
function UIBambooCheckpointDialog:CheckRewardOrFinish()
    local cb
    --如果结束了
    if BambooMgr:GetInstance():IsFinish() then
        cb = function()
            BambooQuestComponent:ClearCurMapInfo()
            self:CloseSelf()
        end
    end

    local t = BambooQuestComponent:GetPassReward()
    --有奖励
    if t and table.count(t) > 0 then
        UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = t, cb = cb}})
    else
        if cb then
            cb()
        end
    end
end

--关闭
function UIBambooCheckpointDialog:CloseSelf()
    --BambooMgr:GetInstance():Clear()
    --CfUtils.SetActive(self.controller.gameObject, false)
    UIModule.BackDialog()
end

