function UIBambooCheckpointDialog:OnBamBooMgrClear()
    self._isClear = true
end

function UIBambooCheckpointDialog:OnUpdate()
    if self._isClear then
        return
    end

    BambooMgr:GetInstance():OnUpdate()

    if Utils.TouchCount() > 0 and (not self.__closing) then
        if self._isClickBuff then
            self._isClickBuff = false
            return
        end
        if self._buffs or table.count(self._buffs) > 0 then
            for k, v in pairs(self._buffs) do
                local go = self["Point"..k]
                if go then
                    local scr = CfUtils.GetLuaScr(go.transform:Find("BambooCheckpointBuffNode"), UIBambooCheckpointBuffNode)
                    if scr then
                        scr:RefreshNormal()
                    end
                end
            end
        end
    end
end

function UIBambooCheckpointDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.15))

        BambooMgr:GetInstance():Init(self._activityUuid, self._mapId, self.CatEmotion)

        local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(CS.Engine.Lib.BehaviourAction))
        if behaviourAction then
            behaviourAction.UpdateAction = Bind(self, self.OnUpdate)
            self._behaviourAction = behaviourAction
        end

        self:FillSelf()

        CfUtils.SetTopCommonCb(function()
            self:OnBtnClose()
        end)

        self._co = cs_coroutine.start(function()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
            BambooMgr:GetInstance():PlayEventFinishAni()

            self:CheckRewardOrFinish()
        end)
    end))
    return coWait
end

function UIBambooCheckpointDialog:OnHide()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self._isClear = true

        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end
    end))
    return coWait
end

function UIBambooCheckpointDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self._co then
            cs_coroutine.stop(self._co)
        end
        for k, v in pairs(self._allCo) do
            if v then
                cs_coroutine.stop(v)
            end
        end
        if not IsNull(self) then
            Events.RemoveListener(Constants.EventNames.EventBambooMainStatus, self.EventBambooMainStatus)
            Events.RemoveListener(Constants.EventNames.BambooActivityEnd, self.EventBambooActivityEnd)
            Events.RemoveListener(Constants.EventNames.BambooBuffChange, self.EventBambooBuffChange)
            Events.RemoveListener(Constants.EventNames.BamBooMgrClear, self.EventBamBooMgrClear)
        end
        BambooMgr:GetInstance():Clear()
        --cs_coroutine.yield_return(BambooMgr:GetInstance():Clear())

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIBambooCheckpointDialog
